	int cpu;

	for_each_online_cpu(cpu) {
		/* No need to roundup ourselves */
		if (cpu == this_cpu)
			continue;

		__ipi_send_single(ipi_desc[IPI_KGDB_ROUNDUP], cpu);
	}
